import {emotions,uid,analyze,imageFor,candidates,validateProject} from './engine.js';
import {installSampleArt} from './sample-pack.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,project,chapterId,tab='text',sceneIndex=0,reading=false,saveQueue=Promise.resolve(),noticeTimer;
const demoText='유나는 안개가 내려앉은 숲의 입구에 멈춰 섰다. 오래된 나무 사이로 푸른 빛이 흔들렸다.\n\n유나는 뒤따라온 시온을 바라보며 미소 지었다. “이번에는 함께 돌아가는 거야.”\n\n시온은 상처 입은 팔을 감쌌다. 어둠 속에서 무언가 다가오자 두려움에 몸이 굳었다.\n\n유나는 동료를 지키기 위해 검을 뽑았다. 분노가 타오르며 검 끝에 붉은 불꽃이 맺혔다. “불꽃 검격!”';
function demo(){const chars=[{id:uid(),name:'유나',aliases:'붉은 검의 기사',description:'동료를 지키는 검사. 샘플 작품의 주인공.',skills:'불꽃 검격'},{id:uid(),name:'시온',aliases:'',description:'유나와 함께 숲에 들어온 동료.',skills:''}];const scenes=analyze(demoText,chars);scenes[3].skill='불꽃 검격';return {version:1,title:'안개 너머의 불꽃',characters:chars,assets:[],chapters:[{id:uid(),title:'1화 · 숲의 입구',text:demoText,scenes}]};}
function notify(t){clearTimeout(noticeTimer);$('#notice').textContent=t;$('#notice').style.display='block';noticeTimer=setTimeout(()=>$('#notice').style.display='none',4500);}
function persist(){const snapshot=structuredClone(project);saveQueue=saveQueue.then(()=>new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);})).then(()=>{const e=$('#save-status');if(e)e.textContent='● 이 브라우저에 저장됨';}).catch(()=>{const e=$('#save-status');if(e)e.textContent='저장 실패 · JSON으로 백업하세요';notify('저장 공간이 부족하거나 저장할 수 없습니다. 프로젝트를 내보내세요.');});return saveQueue;}
const chapter=()=>project.chapters.find(c=>c.id===chapterId)||project.chapters[0];
const scene=()=>chapter().scenes[Math.min(sceneIndex,chapter().scenes.length-1)];
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
function header(){return `<header><div><div class="brand"><span>文</span>Novel Studio</div><div class="subtitle">STORIES INTO SCENES</div></div><div class="actions"><span id="save-status" class="status">● 로컬 프로젝트</span><button data-action="export">프로젝트 내보내기</button><button data-action="import">불러오기</button><button class="primary" data-action="reader">${reading?'에디터로 돌아가기':'▷ 읽기 모드'}</button></div></header>`;}
function sidebar(){return `<aside><div class="overline">Your story / 작품</div><div class="project-name">${esc(project.title)}</div><button class="ghost small" data-action="rename">작품 이름 변경</button><div class="muted" style="margin:24px 0 10px">회차 ${project.chapters.length}개</div>${project.chapters.map((c,i)=>`<button class="chapter ${c.id===chapter().id?'active':''}" data-chapter="${c.id}"><span class="overline">${String(i+1).padStart(2,'0')}</span>　${esc(c.title)}<small>${c.scenes.length}개 장면 · ${c.text.length.toLocaleString()}자</small></button>`).join('')}<button style="width:100%;margin-top:12px" data-action="addChapter">＋ 새 회차 추가</button><div class="sidebar-footer"><div class="overline">PROJECT LIBRARY</div><p class="muted">인물 ${project.characters.length}명 · 이미지 ${project.assets.length}장<br>기존 인물과 이미지는 새 회차에서도 이어집니다.</p><p class="muted">텍스트와 이미지는 이 브라우저에 저장됩니다. 기기를 옮기기 전에 프로젝트를 내보내세요.</p></div></aside>`;}
function stage(s){const c=project.characters.find(c=>c.id===s?.characterId),asset=s?imageFor(project.assets,s):null,bg=project.assets.find(a=>a.id===s?.background);return `<div class="stage">${bg?`<img class="stage-bg" alt="${esc(bg.name)}" src="${bg.data}">`:''}${asset?`<img class="portrait" alt="${esc(c?.name)} · ${esc(asset.emotion)}" src="${asset.data}">`:`<div class="placeholder"><div class="sigil">${esc(c?.name?.[0]||'文')}</div><p>${c?'캐릭터 이미지를 연결해 보세요':'텍스트가 장면이 되는 곳'}</p></div>`}<div class="stage-caption"><div class="row"><strong>${esc(c?.name||'내레이션')}</strong><span class="badge">${esc(s?.emotion||'기본')}</span></div><div class="chips">${s?.condition&&s.condition!=='정상'?`<span class="chip">${esc(s.condition)}</span>`:''}${s?.skill?`<span class="chip">✧ ${esc(s.skill)}</span>`:''}</div><p>${esc(s?.note||s?.text||'텍스트를 입력하고 장면을 만들어 보세요.')}</p></div></div>`;}
function nav(){return `<div class="nav row"><button data-action="prev" ${sceneIndex<=0?'disabled':''}>← 이전</button><span class="muted">${chapter().scenes.length?sceneIndex+1:0} / ${chapter().scenes.length}</span><button data-action="next" ${sceneIndex>=chapter().scenes.length-1?'disabled':''}>다음 →</button></div>`;}
function preview(){const s=scene(),asset=s?imageFor(project.assets,s):null;return `<section class="preview"><div class="overline">LIVE PREVIEW</div><h2 style="margin-top:10px">장면 미리보기</h2>${stage(s)}${nav()}<p class="muted">${asset?(asset.emotion!==s.emotion?'해당 감정 이미지가 없어 기본 이미지를 사용합니다.':'장면에 연결된 이미지를 표시하고 있어요.'):'이미지 보관함에서 인물의 기본·감정 이미지를 등록하세요.'}</p><div class="hint">현재 분석은 규칙 기반 초안입니다. 인물·감정·기술을 검토하고 장면별로 수정할 수 있어요.</div></section>`;}
function textPanel(){const c=chapter();return `<div class="field"><label for="chapter-title">회차 제목</label><input id="chapter-title" value="${esc(c.title)}"></div><div class="field"><div class="row" style="justify-content:space-between;margin-bottom:10px"><label for="source">원문 텍스트</label><button class="small ghost" data-action="txt">TXT 가져오기</button></div><textarea id="source" placeholder="소설 텍스트를 붙여 넣으세요. 빈 줄로 장면을 구분합니다.">${esc(c.text)}</textarea></div><div class="row" style="justify-content:space-between"><span class="muted">빈 줄 기준으로 장면을 나눕니다.</span><button class="primary" data-action="analyze">✧ 장면 분석하기</button></div><div class="hint">등록된 인물 이름·별칭과 감정 단어로 초안을 만듭니다. 인물 후보는 확인 후 추가하며, 기술과 모호한 표현은 직접 지정하세요. 동일한 원문의 기존 장면은 수정 내용을 유지합니다.</div><details><summary>인물 후보 찾아보기</summary><div class="row" style="margin-top:15px">${candidates(c.text).filter(n=>!project.characters.some(x=>x.name===n)).map(n=>`<button class="small" data-candidate="${esc(n)}">＋ ${esc(n)}</button>`).join('')||'<span class="muted">추가할 이름 후보가 없습니다. 인물 탭에서 직접 등록할 수 있어요.</span>'}</div><p class="muted">조사 패턴으로 추정한 후보이며 일반 명사가 섞일 수 있습니다.</p></details>`;}
function scenesPanel(){const s=scene();if(!s)return '<div class="empty">원문 탭에서 텍스트를 입력하고 장면 분석을 실행하세요.</div>';return `<div class="grid2"><div>${chapter().scenes.map((x,i)=>`<div class="card scene-card ${i===sceneIndex?'selected':''}" role="button" tabindex="0" data-scene="${i}"><div class="row"><span class="overline">SCENE ${String(i+1).padStart(2,'0')}</span><span class="badge">${esc(x.emotion)}</span></div><p>${esc(x.text.slice(0,95))}${x.text.length>95?'…':''}</p><span class="muted">${x.locked?'직접 수정됨':'분석 초안'}</span></div>`).join('')}</div><div class="card" style="align-self:start"><h2>장면 ${sceneIndex+1} 설정</h2><div class="field"><label>등장 인물</label><select data-scene-field="characterId">${options([['','내레이션'],...project.characters.map(c=>[c.id,c.name])],s.characterId)}</select></div><div class="grid2"><div class="field"><label>감정</label><select data-scene-field="emotion">${options(emotions.map(e=>[e,e]),s.emotion)}</select></div><div class="field"><label>신체 상태</label><input data-scene-field="condition" value="${esc(s.condition)}"></div></div><div class="field"><label>사용 기술</label><input data-scene-field="skill" list="skills" value="${esc(s.skill)}" placeholder="예: 불꽃 검격"><datalist id="skills">${(project.characters.find(c=>c.id===s.characterId)?.skills||'').split(',').filter(Boolean).map(k=>`<option value="${esc(k.trim())}"></option>`).join('')}</datalist></div><div class="field"><label>배경</label><select data-scene-field="background">${options([['','기본 배경'],...project.assets.filter(a=>a.kind==='background').map(a=>[a.id,a.name])],s.background)}</select></div><div class="field"><label>이미지 위에 표시할 문구 (선택)</label><input data-scene-field="note" value="${esc(s.note)}" placeholder="비워 두면 원문을 표시합니다"></div><p class="muted">변경 내용은 자동 저장됩니다. 읽기 화면은 해당 장면의 상태를 사용합니다.</p></div></div>`;}
function charactersPanel(){return `<div class="row" style="justify-content:space-between;margin-bottom:18px"><span class="muted">작품 전체에서 공유되는 인물 설정</span><button data-action="addCharacter">＋ 인물 추가</button></div>${project.characters.map(c=>`<div class="card"><div class="grid2"><div class="field"><label>이름</label><input data-char="${c.id}" data-field="name" value="${esc(c.name)}"></div><div class="field"><label>별칭 (쉼표로 구분)</label><input data-char="${c.id}" data-field="aliases" value="${esc(c.aliases)}"></div></div><div class="field"><label>인물 설명</label><input data-char="${c.id}" data-field="description" value="${esc(c.description)}"></div><div class="field"><label>보유 기술 (쉼표로 구분)</label><input data-char="${c.id}" data-field="skills" value="${esc(c.skills)}"></div><span class="muted">${project.assets.filter(a=>a.characterId===c.id).length}개의 연결 이미지</span></div>`).join('')||'<div class="empty">인물을 등록하면 새 회차 분석에서 이름을 찾습니다.</div>'}`;}
function assetsPanel(){return `<div class="card"><h2>장면에 이미지를 입히세요</h2><div class="grid3"><div class="field"><label for="asset-kind">이미지 종류</label><select id="asset-kind"><option value="character">캐릭터 이미지</option><option value="background">장면 배경</option></select></div><div class="field"><label for="asset-character">인물</label><select id="asset-character">${options(project.characters.map(c=>[c.id,c.name]),project.characters[0]?.id)}</select></div><div class="field"><label for="asset-emotion">감정</label><select id="asset-emotion">${options(emotions.map(e=>[e,e]),'기본')}</select></div></div><label for="image-upload">이미지 업로드 · PNG / JPG / WebP / GIF · 최대 5 MB</label><input id="image-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><p class="muted">같은 인물·감정으로 업로드하면 기존 이미지를 교체합니다. 기본 표정은 다른 감정 이미지가 없을 때 사용합니다.</p></div><div class="asset-grid">${project.assets.map(a=>`<div class="card"><span class="badge">${a.kind==='background'?'배경':esc(project.characters.find(c=>c.id===a.characterId)?.name||'인물')+' · '+esc(a.emotion)}</span><img class="thumb" src="${a.data}" alt="${esc(a.name)}"><div class="row" style="justify-content:space-between"><span class="muted">${esc(a.name)}</span><button class="small danger" data-remove-asset="${a.id}">삭제</button></div></div>`).join('')}</div><h2 style="margin-top:24px">이 회차에 필요한 이미지</h2>${[...new Set(chapter().scenes.filter(s=>s.characterId&&!project.assets.some(a=>a.kind==='character'&&a.characterId===s.characterId&&a.emotion===s.emotion)).map(s=>`${project.characters.find(c=>c.id===s.characterId)?.name||'인물'} · ${s.emotion}`))].map(t=>`<p class="muted">○ ${esc(t)}</p>`).join('')||'<p class="muted">현재 장면에 필요한 감정 이미지가 모두 준비됐어요.</p>'}`;}
function render(){sceneIndex=Math.max(0,Math.min(sceneIndex,chapter().scenes.length-1));$('#app').innerHTML=header()+(reading?`<div class="reader"><section><div class="overline">${esc(project.title)}</div><h1>${esc(chapter().title)}</h1><div class="row"><label for="read-chapter">회차 선택</label><select id="read-chapter">${options(project.chapters.map(c=>[c.id,c.title]),chapter().id)}</select></div><div class="reader-text">${chapter().scenes.map((s,i)=>`<button class="${sceneIndex===i?'active':''}" data-scene="${i}">${esc(s.text)}</button>`).join('')||'<p class="empty">에디터에서 먼저 장면을 만들어 주세요.</p>'}</div></section><section class="reader-visual"><div class="overline">SCENE ${String(sceneIndex+1).padStart(2,'0')}</div>${stage(scene())}${nav()}<div class="progress"><div style="width:${chapter().scenes.length?(sceneIndex+1)/chapter().scenes.length*100:0}%"></div></div><p class="muted">문단을 선택하거나 ← → 키로 장면을 넘겨 보세요.</p></section></div>`:`<div class="workspace">${sidebar()}<main><div class="intro"><div><div class="overline">STORY WORKSPACE</div><h1>이야기에 장면을 더하다</h1><p class="muted">텍스트를 정리하고, 인물에 표정을 입히세요.</p></div><span class="badge">PROTOTYPE 01</span></div><div class="tabs" role="tablist">${[['text','원문'],['scenes','장면 연출'],['characters','인물 · 기술'],['assets','이미지 보관함']].map(([id,t])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-tab="${id}">${t}</button>`).join('')}</div>${({text:textPanel,scenes:scenesPanel,characters:charactersPanel,assets:assetsPanel})[tab]()}</main>${preview()}</div>`);}
function addCharacter(name){if(!name?.trim())return;name=name.trim();if(project.characters.some(c=>c.name===name)){notify('이미 등록된 이름입니다.');return;}project.characters.push({id:uid(),name,aliases:'',description:'',skills:''});persist();render();}
function filePicker(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>input.files[0]&&callback(input.files[0]);input.click();}
const actions={
 reader(){reading=!reading;render();window.scrollTo(0,0);},prev(){if(sceneIndex>0){sceneIndex--;render();}},next(){if(sceneIndex<chapter().scenes.length-1){sceneIndex++;render();}},
 rename(){const title=prompt('작품 이름',project.title);if(title?.trim()){project.title=title.trim();persist();render();}},
 addChapter(){const c={id:uid(),title:`${project.chapters.length+1}화 · 새로운 이야기`,text:'',scenes:[]};project.chapters.push(c);chapterId=c.id;sceneIndex=0;tab='text';persist();render();},
 addCharacter(){addCharacter(prompt('인물 이름'));},
 analyze(){if(!chapter().text.trim()){notify('먼저 원문 텍스트를 입력하세요.');return;}chapter().scenes=analyze(chapter().text,project.characters,chapter().scenes);sceneIndex=0;tab='scenes';persist();render();notify(`${chapter().scenes.length}개 장면을 만들었습니다. 분석 초안을 검토하세요.`);},
 txt(){filePicker('.txt,text/plain',async f=>{if(f.size>2*1024*1024){notify('텍스트 파일은 2 MB 이하로 넣어 주세요.');return;}if(chapter().text&&!confirm('현재 회차의 원문을 교체할까요? 기존 연출은 재분석 전까지 유지됩니다.'))return;chapter().text=await f.text();persist();render();});},
 export(){const blob=new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${project.title.replace(/[\\/:*?"<>|]/g,'_')}.novel.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('이미지를 포함한 프로젝트를 내보냈습니다.');},
 import(){filePicker('.json,application/json',async f=>{try{if(f.size>80*1024*1024)throw Error('프로젝트는 80 MB 이하만 불러올 수 있습니다.');const incoming=validateProject(JSON.parse(await f.text()));if(!confirm('현재 작업을 불러온 프로젝트로 바꿀까요? 필요한 작업은 먼저 내보내세요.'))return;project=incoming;chapterId=project.chapters[0].id;sceneIndex=0;await persist();render();notify('프로젝트를 불러왔습니다.');}catch(e){notify(e.message||'프로젝트를 읽을 수 없습니다.');}});}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-tab],[data-chapter],[data-scene],[data-candidate],[data-remove-asset]');if(!b)return;if(b.dataset.action)actions[b.dataset.action]?.();else if(b.dataset.tab){tab=b.dataset.tab;render();}else if(b.dataset.chapter){chapterId=b.dataset.chapter;sceneIndex=0;render();}else if(b.dataset.scene){sceneIndex=Number(b.dataset.scene);render();}else if(b.dataset.candidate)addCharacter(b.dataset.candidate);else if(b.dataset.removeAsset){if(!confirm('이 이미지를 삭제할까요?'))return;const id=b.dataset.removeAsset;project.assets=project.assets.filter(a=>a.id!==id);for(const c of project.chapters)for(const s of c.scenes)if(s.background===id)s.background='';persist();render();}});
document.addEventListener('input',e=>{if(e.target.id==='source'){chapter().text=e.target.value;persist();}else if(e.target.id==='chapter-title'){chapter().title=e.target.value;persist();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.sceneField){scene()[el.dataset.sceneField]=el.value;scene().locked=true;persist();render();}else if(el.dataset.char){const c=project.characters.find(c=>c.id===el.dataset.char);if(el.dataset.field==='name'&&!el.value.trim()){el.value=c.name;notify('이름을 입력하세요.');return;}c[el.dataset.field]=el.value;persist();render();}else if(el.id==='read-chapter'){chapterId=el.value;sceneIndex=0;render();window.scrollTo(0,0);}else if(el.id==='image-upload'&&el.files[0]){const f=el.files[0],kind=$('#asset-kind').value,characterId=$('#asset-character').value,emotion=$('#asset-emotion').value;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(f.type)||f.size>5*1024*1024){notify('PNG, JPG, WebP, GIF 이미지를 5 MB 이하로 업로드하세요.');return;}if(kind==='character'&&!characterId){notify('먼저 인물을 추가하세요.');return;}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=data;});const existing=project.assets.find(a=>kind==='character'&&a.kind===kind&&a.characterId===characterId&&a.emotion===emotion);if(existing){existing.data=data;existing.name=f.name;}else project.assets.push({id:uid(),name:f.name,kind,characterId:kind==='character'?characterId:'',emotion,data});await persist();render();notify('이미지를 연결했습니다.');}catch{notify('이미지를 읽을 수 없습니다.');}}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='Enter'&&e.target.matches('[data-scene]'))e.target.click();if(reading&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();actions[e.key==='ArrowLeft'?'prev':'next']();}});
try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('novel-studio-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});project=await new Promise((resolve,reject)=>{const r=db.transaction('projects').objectStore('projects').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});project=project?validateProject(project):demo();chapterId=project.chapters[0].id;render();try{const added=await installSampleArt(project,demoText,async file=>{const response=await fetch(new URL("assets/"+file,import.meta.url));if(!response.ok)throw Error("이미지 파일을 읽을 수 없습니다.");const blob=await response.blob();return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(new Blob([blob],{type:"image/png"}));});});if(added){render();notify("샘플 이미지 6장을 연결했습니다. 읽기 모드에서 확인하세요.");}}catch{notify("샘플 이미지를 읽지 못했습니다. 새로고침해 다시 시도하세요.");}await persist();}catch(e){$('#app').innerHTML='<main><h1>프로젝트를 열 수 없습니다</h1><p>브라우저 저장소 접근을 허용하고 새로고침해 주세요.</p><p id="error-detail"></p></main>';$('#error-detail').textContent=e.message;}
